-- Optional MySQL schema for migration/reference.
CREATE DATABASE IF NOT EXISTS college_erp;
USE college_erp;
CREATE TABLE IF NOT EXISTS students (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(150) NOT NULL, email VARCHAR(150), roll_number VARCHAR(50) UNIQUE, prn VARCHAR(50), department VARCHAR(100), year VARCHAR(50));
CREATE TABLE IF NOT EXISTS faculty (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(150) NOT NULL, email VARCHAR(150), department VARCHAR(100), designation VARCHAR(100));
CREATE TABLE IF NOT EXISTS attendance (id INT AUTO_INCREMENT PRIMARY KEY, student_id INT NOT NULL, subject VARCHAR(120) NOT NULL, attendance_date DATE NOT NULL, status ENUM('Present','Absent') NOT NULL, FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS marks (id INT AUTO_INCREMENT PRIMARY KEY, student_id INT NOT NULL, subject VARCHAR(120) NOT NULL, marks_obtained DECIMAL(7,2) NOT NULL, total_marks DECIMAL(7,2) NOT NULL, FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS notices (id INT AUTO_INCREMENT PRIMARY KEY, title VARCHAR(200) NOT NULL, message TEXT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS timetable (id INT AUTO_INCREMENT PRIMARY KEY, day VARCHAR(20) NOT NULL, start_time VARCHAR(20) NOT NULL, end_time VARCHAR(20) NOT NULL, subject VARCHAR(120) NOT NULL, faculty VARCHAR(150), room VARCHAR(50));
